def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Connect 1s that lie on the same diagonal.
    lines = []
    for kind in (0, 1):  # 0: r-c constant; 1: r+c constant
        groups = {}
        for r, c in ones:
            key = r - c if kind == 0 else r + c
            groups.setdefault(key, []).append((r, c))

        for key, pts in groups.items():
            if len(pts) < 2:
                continue
            a = min(pts)
            b = max(pts)
            lines.append((kind, key, a, b))

            dr = 1 if b[0] > a[0] else -1
            dc = 1 if b[1] > a[1] else -1
            r, c = a
            while True:
                if grid[r][c] == background:
                    out[r][c] = 1
                if (r, c) == b:
                    break
                r += dr
                c += dc

    # Each 6 on one of those connecting segments extends as a 6-line
    # along the perpendicular diagonal, across the whole grid.
    for kind, key, a, b in lines:
        for r, c in sixes:
            on_segment_line = (r - c == key) if kind == 0 else (r + c == key)
            if not on_segment_line or not (a[0] <= r <= b[0]):
                continue

            perpendicular_key = r + c if kind == 0 else r - c
            for rr in range(h):
                cc = perpendicular_key - rr if kind == 0 else rr - perpendicular_key
                if 0 <= cc < w and grid[rr][cc] == background:
                    out[rr][cc] = 6

    return out
